DROP TABLE IF EXISTS `tabla_artistas_canciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tabla_artistas_canciones` (
  `id_unico` int NOT NULL AUTO_INCREMENT,
  `id` text,
  `artist_name` varchar(255) DEFAULT NULL,
  `track_name` text,
  `genre` text,
  `year` bigint DEFAULT NULL,
  PRIMARY KEY (`id_unico`),
  KEY `fk_artista_cancion` (`artist_name`),
  CONSTRAINT `fk_artista_cancion` FOREIGN KEY (`artist_name`) REFERENCES `tabla_artistas_limpia` (`artista`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11730 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

